    "marked": "^12.0.2"
  },
  "devDependencies": {
    "@types/jest": "^29.5.12",
    "@types/node": "^20.14.9",
    "jest": "^29.7.0",
    "ts-jest": "^29.1.5",
    "typescript": "^5.5.3"
  }
}

import matter from 'gray-matter';

export interface FrontmatterData {
  title?: string;
  date?: string;
  tags?: string[];
  [key: string]: unknown;
}

export interface ParsedMarkdown {
  data: FrontmatterData;
  content: string;
}

/**
 * gray-matter only parses JSON frontmatter out of the box, so the raw
 * `---`-delimited YAML block is extracted here and parsed with a simple
 * key: value splitter, then merged on top of gray-matter's own output.
 */
export function parseFrontmatter(raw: string): ParsedMarkdown {
  const gm = matter(raw);
  const { block } = extractFrontmatterBlock(raw);
  const yamlData = parseSimpleYaml(block);
  const data: FrontmatterData = { ...gm.data, ...yamlData };

  if (typeof data.tags === 'string') {
    data.tags = splitList(data.tags);
  }

  return { data, content: gm.content };
}

function extractFrontmatterBlock(raw: string): { block: string; content: string } {
  const match = raw.match(/^---\r?\n([\s\S]*?)\r?\n---\r?\n?([\s\S]*)$/);
  if (!match) {
    return { block: '', content: raw };
  }
  return { block: match[1], content: match[2] };
}

function parseSimpleYaml(block: string): Record<string, unknown> {
  const data: Record<string, unknown> = {};
  const lines = block.split(/\r?\n/);

  for (const line of lines) {
    const trimmed = line.trim();
    if (!trimmed || trimmed.startsWith('#')) continue;

    const separatorIndex = trimmed.indexOf(':');
    if (separatorIndex === -1) continue;

    const key = trimmed.slice(0, separatorIndex).trim();
    const rawValue = trimmed.slice(separatorIndex + 1).trim();
    if (!key) continue;

    data[key] = parseValue(rawValue);
  }

  return data;
}

function parseValue(value: string): unknown {
  if (value.startsWith('[') && value.endsWith(']')) {
    return splitList(value.slice(1, -1));
  }
  return stripQuotes(value);
}

function splitList(value: string): string[] {
  return value
    .split(',')
    .map((item) => stripQuotes(item.trim()))
    .filter((item) => item.length > 0);
}

function stripQuotes(value: string): string {
  if (value.length >= 2) {
    const first = value[0];
    const last = value[value.length - 1];
    if ((first === '"' && last === '"') || (first === "'" && last === "'")) {
      return value.slice(1, -1);
    }
  }
  return value;
}

export interface Page {
  /** URL-safe identifier derived from the source file path, used as the output file name. */
  slug: string;
  title: string;
  date?: string;
  tags: string[];
  /** Rendered HTML body (without the surrounding page template). */
  html: string;
  /** Path to the source Markdown file, relative to the content directory. */
  sourcePath: string;
  outputFile: string;
}

import { marked } from 'marked';
import type { Page } from './types';

export function renderMarkdown(markdown: string): string {
  return marked.parse(markdown, { async: false }) as string;
}

function escapeHtml(value: string): string {
  return value
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;');
}

function renderTags(tags: string[]): string {
  if (tags.length === 0) return '';
  const items = tags.map((tag) => `<span class="tag">${escapeHtml(tag)}</span>`).join(' ');
  return `<div class="tags">${items}</div>`;
}

export function renderPageHtml(page: Page): string {
  const dateHtml = page.date ? `<p class="date">${escapeHtml(page.date)}</p>` : '';
  return `<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>${escapeHtml(page.title)}</title>
</head>
<body>
  <nav><a href="index.html">&larr; Back to index</a></nav>
  <article>
    <h1>${escapeHtml(page.title)}</h1>
    ${dateHtml}
    ${renderTags(page.tags)}
    ${page.html}
  </article>
</body>
</html>
`;
}

export function renderIndexHtml(pages: Page[]): string {
  const items = pages
    .map((page) => {
      const dateHtml = page.date ? ` <span class="date">${escapeHtml(page.date)}</span>` : '';
      return `    <li>
      <a href="${escapeHtml(page.outputFile)}">${escapeHtml(page.title)}</a>${dateHtml}
      ${renderTags(page.tags)}
    </li>`;
    })
    .join('\n');

  return `<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>Home</title>
</head>
<body>
  <h1>All Pages</h1>
  <ul>
${items}
  </ul>
</body>
</html>
`;
}

import * as fs from 'fs';
import * as path from 'path';
import { parseFrontmatter } from './frontmatter';
import { renderMarkdown, renderPageHtml, renderIndexHtml } from './render';
import type { Page } from './types';

export interface BuildOptions {
  contentDir: string;
  outputDir: string;
}

export interface BuildResult {
  pages: Page[];
  outputDir: string;
}

export function build(options: BuildOptions): BuildResult {
  const { contentDir, outputDir } = options;

  if (!fs.existsSync(contentDir) || !fs.statSync(contentDir).isDirectory()) {
    throw new Error(`Content directory not found: ${contentDir}`);
  }

  const markdownFiles = findMarkdownFiles(contentDir);
  const pages = markdownFiles.map((filePath) => buildPage(filePath, contentDir));
  pages.sort(comparePages);

  fs.mkdirSync(outputDir, { recursive: true });

  for (const page of pages) {
    const outPath = path.join(outputDir, page.outputFile);
    fs.mkdirSync(path.dirname(outPath), { recursive: true });
    fs.writeFileSync(outPath, renderPageHtml(page), 'utf8');
  }

  fs.writeFileSync(path.join(outputDir, 'index.html'), renderIndexHtml(pages), 'utf8');

  return { pages, outputDir };
}

function comparePages(a: Page, b: Page): number {
  if (a.date && b.date) return b.date.localeCompare(a.date);
  if (a.date) return -1;
  if (b.date) return 1;
  return a.title.localeCompare(b.title);
}

function findMarkdownFiles(dir: string): string[] {
  const entries = fs.readdirSync(dir, { withFileTypes: true });
  const files: string[] = [];

  for (const entry of entries) {
    const fullPath = path.join(dir, entry.name);
    if (entry.isDirectory()) {
      files.push(...findMarkdownFiles(fullPath));
    } else if (entry.isFile() && /\.md$/i.test(entry.name)) {
      files.push(fullPath);
    }
  }

  return files;
}

function buildPage(filePath: string, contentDir: string): Page {
  const raw = fs.readFileSync(filePath, 'utf8');
  const { data, content } = parseFrontmatter(raw);
  const html = renderMarkdown(content);

  const relativePath = path.relative(contentDir, filePath);
  const slug = slugify(relativePath);
  const title = typeof data.title === 'string' && data.title.trim() ? data.title : slug;
  const date = typeof data.date === 'string' && data.date.trim() ? data.date : undefined;
  const tags = Array.isArray(data.tags) ? data.tags.map(String) : [];

  return {
    slug,
    title,
    date,
    tags,
    html,
    sourcePath: relativePath,
    outputFile: `${slug}.html`,
  };
}

function slugify(relativePath: string): string {
  const withoutExt = relativePath.replace(/\.md$/i, '');
  const slug = withoutExt
    .split(path.sep)
    .join('-')
    .toLowerCase()
    .replace(/[^a-z0-9-]+/g, '-')
    .replace(/-+/g, '-')
    .replace(/^-|-$/g, '');

  // "index" is reserved for the generated listing page.
  if (!slug || slug === 'index') return slug === 'index' ? 'index-page' : 'page';
  return slug;
}

#!/usr/bin/env node
import { Command } from 'commander';
import * as path from 'path';
import { build } from './generator';

export function createCli(): Command {
  const program = new Command();

  program
    .name('ssg')
    .description('A static site generator for Markdown content');

  program
    .command('build')
    .description('Generate the static site')
    .option('--content <dir>', 'content directory to read Markdown files from', './content')
    .option('--output <dir>', 'output directory to write the generated site to', './dist')
    .action((opts: { content: string; output: string }) => {
      const contentDir = path.resolve(process.cwd(), opts.content);
      const outputDir = path.resolve(process.cwd(), opts.output);
      const result = build({ contentDir, outputDir });
      // eslint-disable-next-line no-console
      console.log(`Built ${result.pages.length} page(s) into ${result.outputDir}`);
    });

  return program;
}

export function run(argv: string[]): void {
  createCli().parse(argv);
}

if (require.main === module) {
  run(process.argv);
}

export { build } from './generator';
export type { BuildOptions, BuildResult } from './generator';
export { parseFrontmatter } from './frontmatter';
export type { FrontmatterData, ParsedMarkdown } from './frontmatter';
export { renderMarkdown, renderPageHtml, renderIndexHtml } from './render';
export type { Page } from './types';

import { parseFrontmatter } from '../src/frontmatter';

describe('parseFrontmatter', () => {
  it('parses title, date, and bracketed tags from a YAML frontmatter block', () => {
    const raw = `---
title: My First Post
date: 2024-01-15
tags: [typescript, ssg, testing]
---
# Hello

This is the body.
`;

    const { data, content } = parseFrontmatter(raw);

    expect(data.title).toBe('My First Post');
    expect(data.date).toBe('2024-01-15');
    expect(data.tags).toEqual(['typescript', 'ssg', 'testing']);
    expect(content.trim()).toBe('# Hello\n\nThis is the body.'.trim());
  });

  it('parses comma-separated tags without brackets', () => {
    const raw = `---
title: Second Post
tags: foo, bar
---
Body text.
`;

    const { data } = parseFrontmatter(raw);
    expect(data.tags).toEqual(['foo', 'bar']);
  });

  it('strips quotes around scalar values', () => {
    const raw = `---
title: "Quoted Title"
date: '2024-02-01'
---
Body.
`;

    const { data } = parseFrontmatter(raw);
    expect(data.title).toBe('Quoted Title');
    expect(data.date).toBe('2024-02-01');
  });

  it('returns empty data and full content when there is no frontmatter block', () => {
    const raw = '# Just Markdown\n\nNo frontmatter here.\n';
    const { data, content } = parseFrontmatter(raw);

    expect(data.title).toBeUndefined();
    expect(content).toBe(raw);
  });

  it('handles an empty tags list', () => {
    const raw = `---
title: No Tags
tags: []
---
Body.
`;
    const { data } = parseFrontmatter(raw);
    expect(data.tags).toEqual([]);
  });
});

import { renderMarkdown, renderPageHtml, renderIndexHtml } from '../src/render';
import type { Page } from '../src/types';

describe('renderMarkdown', () => {
  it('converts Markdown to HTML', () => {
    const html = renderMarkdown('# Title\n\nSome **bold** text.');
    expect(html).toContain('<h1>Title</h1>');
    expect(html).toContain('<strong>bold</strong>');
  });
});

describe('renderPageHtml', () => {
  const page: Page = {
    slug: 'my-post',
    title: 'My <Post>',
    date: '2024-01-01',
    tags: ['a', 'b'],
    html: '<p>Body</p>',
    sourcePath: 'my-post.md',
    outputFile: 'my-post.html',
  };

  it('escapes the title and includes metadata and body html', () => {
    const html = renderPageHtml(page);
    expect(html).toContain('My &lt;Post&gt;');
    expect(html).toContain('2024-01-01');
    expect(html).toContain('<span class="tag">a</span>');
    expect(html).toContain('<span class="tag">b</span>');
    expect(html).toContain('<p>Body</p>');
    expect(html).toContain('href="index.html"');
  });
});

describe('renderIndexHtml', () => {
  it('lists every page with a link to its output file', () => {
    const pages: Page[] = [
      {
        slug: 'a',
        title: 'Page A',
        date: '2024-01-02',
        tags: [],
        html: '',
        sourcePath: 'a.md',
        outputFile: 'a.html',
      },
      {
        slug: 'b',
        title: 'Page B',
        tags: ['x'],
        html: '',
        sourcePath: 'b.md',
        outputFile: 'b.html',
      },
    ];

    const html = renderIndexHtml(pages);
    expect(html).toContain('href="a.html"');
    expect(html).toContain('Page A');
    expect(html).toContain('href="b.html"');
    expect(html).toContain('Page B');
    expect(html).toContain('<span class="tag">x</span>');
  });
});

import * as fs from 'fs';
import * as os from 'os';
import * as path from 'path';
import { build } from '../src/generator';

function makeTempDir(prefix: string): string {
  return fs.mkdtempSync(path.join(os.tmpdir(), prefix));
}

describe('build', () => {
  let contentDir: string;
  let outputDir: string;

  beforeEach(() => {
    contentDir = makeTempDir('ssg-content-');
    outputDir = makeTempDir('ssg-output-');

    fs.writeFileSync(
      path.join(contentDir, 'first-post.md'),
      `---
title: First Post
date: 2024-03-01
tags: [intro, news]
---
# Welcome

This is the **first** post.
`
    );

    fs.writeFileSync(
      path.join(contentDir, 'second-post.md'),
      `---
title: Second Post
date: 2024-05-10
tags: [update]
---
Some more content here.
`
    );

    fs.mkdirSync(path.join(contentDir, 'nested'));
    fs.writeFileSync(
      path.join(contentDir, 'nested', 'third-post.md'),
      `---
title: Nested Post
---
Nested content.
`
    );
  });

  afterEach(() => {
    fs.rmSync(contentDir, { recursive: true, force: true });
    fs.rmSync(outputDir, { recursive: true, force: true });
  });

  it('throws when the content directory does not exist', () => {
    expect(() =>
      build({ contentDir: path.join(contentDir, 'nope'), outputDir })
    ).toThrow();
  });

  it('generates a page for every Markdown file, including nested ones', () => {
    const result = build({ contentDir, outputDir });

    expect(result.pages).toHaveLength(3);
    expect(fs.existsSync(path.join(outputDir, 'first-post.html'))).toBe(true);
    expect(fs.existsSync(path.join(outputDir, 'second-post.html'))).toBe(true);
    expect(fs.existsSync(path.join(outputDir, 'nested-third-post.html'))).toBe(true);
  });

  it('generates an index.html listing all pages', () => {
    build({ contentDir, outputDir });

    const indexHtml = fs.readFileSync(path.join(outputDir, 'index.html'), 'utf8');
    expect(indexHtml).toContain('First Post');
    expect(indexHtml).toContain('Second Post');
    expect(indexHtml).toContain('Nested Post');
    expect(indexHtml).toContain('href="first-post.html"');
    expect(indexHtml).toContain('href="second-post.html"');
    expect(indexHtml).toContain('href="nested-third-post.html"');
  });

  it('renders frontmatter metadata and markdown body into each page', () => {
    build({ contentDir, outputDir });

    const pageHtml = fs.readFileSync(path.join(outputDir, 'first-post.html'), 'utf8');
    expect(pageHtml).toContain('<h1>First Post</h1>');
    expect(pageHtml).toContain('2024-03-01');
    expect(pageHtml).toContain('<span class="tag">intro</span>');
    expect(pageHtml).toContain('<h1>Welcome</h1>');
    expect(pageHtml).toContain('<strong>first</strong>');
  });

  it('sorts pages by date descending, undated pages last', () => {
    const result = build({ contentDir, outputDir });
    const titles = result.pages.map((p) => p.title);
    expect(titles).toEqual(['Second Post', 'First Post', 'Nested Post']);
  });
});

import * as fs from 'fs';
import * as os from 'os';
import * as path from 'path';
import { run } from '../src/cli';

function makeTempDir(prefix: string): string {
  return fs.mkdtempSync(path.join(os.tmpdir(), prefix));
}

describe('ssg build CLI', () => {
  let contentDir: string;
  let outputDir: string;
  let logSpy: jest.SpyInstance;

  beforeEach(() => {
    contentDir = makeTempDir('ssg-cli-content-');
    outputDir = makeTempDir('ssg-cli-output-');

    fs.writeFileSync(
      path.join(contentDir, 'hello.md'),
      `---
title: Hello CLI
date: 2024-06-01
tags: [cli]
---
Hello from the CLI test.
`
    );

    logSpy = jest.spyOn(console, 'log').mockImplementation(() => undefined);
  });

  afterEach(() => {
    fs.rmSync(contentDir, { recursive: true, force: true });
    fs.rmSync(outputDir, { recursive: true, force: true });
    logSpy.mockRestore();
  });

  it('builds the site using --content and --output options', () => {
    run(['node', 'ssg', 'build', '--content', contentDir, '--output', outputDir]);

    expect(fs.existsSync(path.join(outputDir, 'index.html'))).toBe(true);
    expect(fs.existsSync(path.join(outputDir, 'hello.html'))).toBe(true);

    const pageHtml = fs.readFileSync(path.join(outputDir, 'hello.html'), 'utf8');
    expect(pageHtml).toContain('Hello CLI');
    expect(logSpy).toHaveBeenCalledWith(expect.stringContaining('Built 1 page(s)'));
  });
});
